 onReset: () => void;
}

const SEVERITIES = [
 { value: "", label: "All Severities" },
 { value: "critical", label: "Critical" },
 { value: "high", label: "High" },
 { value: "medium", label: "Medium" },
 { value: "low", label: "Low" },
];

const STATUSES = [
 { value: "", label: "All Statuses" },
 { value: "open", label: "Open" },
 { value: "acknowledged", label: "Acknowledged" },
 { value: "in_progress", label: "In Progress" },
 { value: "resolved", label: "Resolved" },
 { value: "dismissed", label: "Dismissed" },
];

export default function FilterBar(
 { filters, alertTypes, onFilterChange, onReset }: Props
) {
 const set = (key: keyof AlertFilters, val: string) =>
 onFilterChange({ ...filters, [key]: val });
 const typeOpts = [{ value: "", label: "All Types" }, ...alertTypes];

 return (
 <div className="filter-bar">
 <div className="filter-bar__fields">
 <div className="filter-group">
 <label className="filter-label">Search</label>
 <input className="filter-input" type="text"
 placeholder="Search alerts..." value={filters.search || ""}
 onChange={(e) => set("search", e.target.value)} />
 </div>
 <div className="filter-group">
 <label className="filter-label">Severity</label>
 <select className="filter-select" value={filters.severity || ""}
 onChange={(e) => set("severity", e.target.value)}>
 {SEVERITIES.map((o) => (
 <option key={o.value} value={o.value}>{o.label}</option>
 ))}
 </select>
 </div>
 <div className="filter-group">
 <label className="filter-label">Type</label>
 <select className="filter-select" value={filters.alert_type || ""}
 onChange={(e) => set("alert_type", e.target.value)}>
 {typeOpts.map((o) => (
 <option key={o.value} value={o.value}>{o.label}</option>
 ))}
 </select>
 </div>
 <div className="filter-group">
 <label className="filter-label">Status</label>
 <select className="filter-select" value={filters.status || ""}
 onChange={(e) => set("status", e.target.value)}>
 {STATUSES.map((o) => (
 <option key={o.value} value={o.value}>{o.label}</option>
 ))}
 </select>
 </div>
 <div className="filter-group">
 <label className="filter-label">From</label>
 <input className="filter-input" type="date"
 value={filters.date_from || ""}
 onChange={(e) => set("date_from", e.target.value)} />
 </div>
 <div className="filter-group">
 <label className="filter-label">To</label>
 <input className="filter-input" type="date"
 value={filters.date_to || ""}
 onChange={(e) => set("date_to", e.target.value)} />
 </div>
 </div>
 <button className="btn btn--reset" onClick={onReset}>Reset</button>
 </div>
 );
}
