","import React from "react";
import SeverityBadge from "./SeverityBadge";
import StatusBadge from "./StatusBadge";
import type { Alert } from "../services/alertService";

interface Props {
 alerts: Alert[];
}

const ALERT_TABLE = "x_2056099_indust_0_inv_alert";

function formatDate(d: string): string {
 if (!d) return "\u2014";
 try {
 return new Date(d).toLocaleDateString("en-US", {
 month: "short", day: "numeric", year: "numeric",
 });
 } catch { return d; }
}

export default function AlertTable({ alerts }: Props) {
 return (
 <div className="table-container">
 <table className="alert-table">
 <thead>
 <tr>
 <th>Severity</th>
 <th>Alert / Description</th>
 <th>Category</th>
 <th>Related Record</th>
 <th>Created</th>
 <th>Status</th>
 <th>Action</th>
 </tr>
 </thead>
 <tbody>
 {alerts.map((a) => (
 <tr key={a.sys_id}>
 <td>
 <SeverityBadge severity={a.severity}
 label={a.severityDisplay} />
 </td>
 <td>
 <div className="alert-cell">
 <span className="alert-cell__number">{a.number}</span>
 <span className="alert-cell__msg">{a.alert_message}</span>
 </div>
 </td>
 <td>{a.alertTypeDisplay}</td>
 <td>
 {a.relatedRecord ? (
 <a className="record-link"
 href={`/${a.relatedRecord.table}.do?sys_id=${a.relatedRecord.sys_id}`}
 target="_blank" rel="noopener noreferrer">
 {a.relatedRecord.label}
 </a>
 ) : "\u2014"}
 </td>
 <td className="nowrap">{formatDate(a.alert_date)}</td>
 <td>
 <StatusBadge status={a.status} label={a.statusDisplay} />
 </td>
 <td>
 <button className="btn btn--view"
 onClick={() => window.open(
 `/${ALERT_TABLE}.do?sys_id=${a.sys_id}`, "_blank"
 )}>
 View
 </button>
 </td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 );
}
