","/** Types and API service for the Alerts & Exceptions page */

export interface AlertSummary {
 critical: number;
 high: number;
 medium: number;
 low: number;
 open: number;
 resolved: number;
}

export interface AlertTypeOption {
 value: string;
 label: string;
}

export interface RelatedRecord {
 type: string;
 label: string;
 table: string;
 sys_id: string;
}

export interface Alert {
 sys_id: string;
 number: string;
 severity: string;
 severityDisplay: string;
 alert_type: string;
 alertTypeDisplay: string;
 alert_message: string;
 status: string;
 statusDisplay: string;
 alert_date: string;
 resolved_date: string;
 current_quantity: number;
 threshold_quantity: number;
 material_product: string;
 material_product_id: string;
 assigned_to: string;
 resolution_notes: string;
 relatedRecord: RelatedRecord | null;
}

export interface AlertFilters {
 search?: string;
 severity?: string;
 alert_type?: string;
 status?: string;
 date_from?: string;
 date_to?: string;
}

export interface AlertResponse {
 summary: AlertSummary;
 total: number;
 limit: number;
 offset: number;
 alertTypes: AlertTypeOption[];
 alerts: Alert[];
}

const API_BASE = "/api/x_2056099_indust_0/alert_center_api";

export async function fetchAlerts(
 filters: AlertFilters = {},
 limit = 25,
 offset = 0
): Promise<AlertResponse> {
 const params = new URLSearchParams();
 if (filters.search) params.set("search", filters.search);
 if (filters.severity) params.set("severity", filters.severity);
 if (filters.alert_type) params.set("alert_type", filters.alert_type);
 if (filters.status) params.set("status", filters.status);
 if (filters.date_from) params.set("date_from", filters.date_from);
 if (filters.date_to) params.set("date_to", filters.date_to);
 params.set("limit", String(limit));
 params.set("offset", String(offset));

 const res = await fetch(`${API_BASE}/alerts?${params}`, {
 headers: {
 Accept: "application/json",
 "X-UserToken": (window as any).g_ck || "",
 },
 });

 if (!res.ok) throw new Error(`API error: ${res.status}`);
 const json = await res.json();
 return json.result;
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","/* ===== Aliases ===== */
:root {
 --ac-bg: rgb(var(--now-color_background--primary, 255, 255, 255));
 --ac-bg-alt: rgb(var(--now-color_background--secondary, 245, 246, 247));
 --ac-text: rgb(var(--now-color_text--primary, 16, 23, 26));
 --ac-text-muted: rgb(var(--now-color_text--secondary, 75, 85, 89));
 --ac-border: rgb(var(--now-container--border-color, 207, 213, 215));
 --ac-primary: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 --ac-primary-hover: rgb(var(--now-actionable--primary--background-color--hover, 0, 138, 173));
 --ac-on-primary: rgb(var(--now-actionable_label--primary--color, 255, 255, 255));
 --ac-radius: var(--now-container--border-radius, 8px);
 --ac-space-sm: var(--now-static-space--sm, 0.5rem);
 --ac-space-md: var(--now-static-space--md, 0.75rem);
 --ac-space-lg: var(--now-static-space--lg, 1rem);
 --ac-space-xl: var(--now-static-space--xl, 1.5rem);
 --ac-font: var(--now-font-family, system-ui, sans-serif);
}

/* ===== Page Layout ===== */
.alerts-page {
 max-width: 1400px;
 margin: 0 auto;
 padding: var(--ac-space-xl);
 font-family: var(--ac-font);
 color: var(--ac-text);
 background: var(--ac-bg);
}
.alerts-header { margin-bottom: var(--ac-space-xl); }
.alerts-header__title {
 margin: 0 0 var(--ac-space-sm);
 font-size: var(--now-static-font-size--xl, 1.5rem);
 font-weight: 700;
}
.alerts-header__subtitle {
 margin: 0;
 color: var(--ac-text-muted);
 font-size: var(--now-static-font-size--md, 1rem);
}

/* ===== Summary Cards ===== */
.summary-cards {
 display: grid;
 grid-template-columns: repeat(6, 1fr);
 gap: var(--ac-space-md);
 margin-bottom: var(--ac-space-xl);
}
.summary-card {
 display: flex;
 flex-direction: column;
 align-items: center;
 padding: var(--ac-space-lg);
 border-radius: var(--ac-radius);
 border: 1px solid var(--ac-border);
 background: var(--ac-bg);
 box-shadow: var(--now-static-drop-shadow--sm);
}
.summary-card__count { font-size: 2rem; font-weight: 700; line-height: 1.2; }
.summary-card__label {
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--ac-text-muted);
 margin-top: var(--ac-space-sm);
 text-transform: uppercase;
 letter-spacing: 0.05em;
}
.summary-card--critical { border-top: 3px solid rgb(var(--now-indicator--primary_critical--background-color, 229, 34, 57)); }
.summary-card--critical .summary-card__count { color: rgb(var(--now-indicator--primary_critical--background-color, 229, 34, 57)); }
.summary-card--high { border-top: 3px solid rgb(235, 117, 27); }
.summary-card--high .summary-card__count { color: rgb(235, 117, 27); }
.summary-card--medium { border-top: 3px solid rgb(var(--now-indicator--primary_warning--background-color, 204, 158, 0)); }
.summary-card--medium .summary-card__count { color: rgb(var(--now-indicator--primary_warning--background-color, 204, 158, 0)); }
.summary-card--low { border-top: 3px solid rgb(var(--now-indicator--primary_positive--background-color, 62, 134, 0)); }
.summary-card--low .summary-card__count { color: rgb(var(--now-indicator--primary_positive--background-color, 62, 134, 0)); }
.summary-card--open { border-top: 3px solid rgb(var(--now-indicator--primary_info--background-color, 0, 128, 163)); }
.summary-card--open .summary-card__count { color: rgb(var(--now-indicator--primary_info--background-color, 0, 128, 163)); }
.summary-card--resolved { border-top: 3px solid var(--ac-text-muted); }
.summary-card--resolved .summary-card__count { color: var(--ac-text-muted); }

/* ===== Filter Bar ===== */
.filter-bar {
 display: flex;
 align-items: flex-end;
 gap: var(--ac-space-md);
 margin-bottom: var(--ac-space-xl);
 padding: var(--ac-space-lg);
 background: var(--ac-bg-alt);
 border-radius: var(--ac-radius);
 border: 1px solid var(--ac-border);
}
.filter-bar__fields { display: flex; flex-wrap: wrap; gap: var(--ac-space-md); flex: 1; }
.filter-group { display: flex; flex-direction: column; min-width: 140px; }
.filter-label {
 font-size: var(--now-static-font-size--sm, 0.75rem);
 font-weight: 600;
 color: var(--ac-text-muted);
 margin-bottom: var(--ac-space-sm);
}
.filter-input,
.filter-select {
 height: 2.25rem;
 padding: 0 var(--ac-space-md);
 border: 1px solid rgb(var(--now-form-control-input--primary--border-color, 115, 127, 132));
 border-radius: var(--now-form-control-input--primary--border-radius, 2px);
 background: var(--ac-bg);
 color: var(--ac-text);
 font-family: var(--ac-font);
 font-size: var(--now-static-font-size--md, 1rem);
}
.filter-input:focus,
.filter-select:focus {
 outline: none;
 border-color: rgb(var(--now-form-control-input--primary--border-color--focus, 53, 147, 37));
 box-shadow: inset 0 0 0 1px rgb(var(--now-form-control_focus-ring--primary--color, 53, 147, 37));
}

/* ===== Buttons ===== */
.btn {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 padding: 0.5rem 1rem;
 border: 1px solid transparent;
 border-radius: var(--now-actionable--border-radius, 6px);
 font-family: var(--ac-font);
 font-size: var(--now-static-font-size--sm, 0.75rem);
 cursor: pointer;
 white-space: nowrap;
 transition: background-color 100ms linear;
}
.btn--reset {
 background: var(--ac-bg);
 color: var(--ac-primary);
 border-color: var(--ac-primary);
}
.btn--reset:hover {
 background: rgba(var(--now-actionable--secondary--background-color, 0, 113, 143), 0.08);
}
.btn--view {
 background: var(--ac-primary);
 color: var(--ac-on-primary);
 border-color: var(--ac-primary);
 font-size: 0.75rem;
 padding: 0.25rem 0.75rem;
}
.btn--view:hover { background: var(--ac-primary-hover); }

/* ===== Alert Table ===== */
.table-container {
 overflow-x: auto;
 border: 1px solid var(--ac-border);
 border-radius: var(--ac-radius);
 margin-bottom: var(--ac-space-lg);
}
.alert-table { width: 100%; border-collapse: collapse; }
.alert-table th,
.alert-table td {
 padding: var(--ac-space-md) var(--ac-space-lg);
 text-align: left;
 border-bottom: 1px solid var(--ac-border);
 font-size: var(--now-static-font-size--sm, 0.75rem);
}
.alert-table thead {
 background: rgb(var(--now-color_background--tertiary, 226, 229, 231));
 font-weight: 600;
}
.alert-table tbody tr { background: var(--ac-bg); }
.alert-table tbody tr:hover {
 background: rgba(var(--now-color--primary-1, 245, 246, 247), 0.1);
}
.alert-cell { display: flex; flex-direction: column; gap: 0.125rem; }
.alert-cell__number { font-weight: 600; color: var(--ac-primary); }
.alert-cell__msg {
 color: var(--ac-text-muted);
 max-width: 300px;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}
.nowrap { white-space: nowrap; }
.record-link { color: var(--ac-primary); text-decoration: none; }
.record-link:hover { text-decoration: underline; }

/* ===== Severity Badges ===== */
.severity-badge {
 display: inline-flex;
 align-items: center;
 padding: 0.125rem 0.5rem;
 border-radius: 999px;
 font-size: 0.6875rem;
 font-weight: 600;
 text-transform: capitalize;
 white-space: nowrap;
}
.severity-badge--critical {
 background: rgb(var(--now-indicator--primary_critical--background-color, 229, 34, 57));
 color: rgb(var(--now-indicator_label--primary_critical--color, 255, 255, 255));
}
.severity-badge--high { background: rgb(235, 117, 27); color: #fff; }
.severity-badge--medium {
 background: rgb(var(--now-indicator--primary_warning--background-color, 204, 158, 0));
 color: rgb(var(--now-indicator_label--primary_warning--color, 255, 255, 255));
}
.severity-badge--low {
 background: rgb(var(--now-indicator--primary_positive--background-color, 62, 134, 0));
 color: rgb(var(--now-indicator_label--primary_positive--color, 255, 255, 255));
}

/* ===== Status Badges ===== */
.status-badge {
 display: inline-flex;
 align-items: center;
 padding: 0.125rem 0.5rem;
 border-radius: 999px;
 font-size: 0.6875rem;
 font-weight: 600;
 text-transform: capitalize;
 white-space: nowrap;
}
.status-badge--open {
 background: rgba(var(--now-indicator--primary_info--background-color, 0, 128, 163), 0.15);
 color: rgb(var(--now-indicator--primary_info--background-color, 0, 128, 163));
}
.status-badge--acknowledged,
.status-badge--in-progress {
 background: rgba(var(--now-indicator--primary_warning--background-color, 204, 158, 0), 0.15);
 color: rgb(133, 103, 0);
}
.status-badge--resolved {
 background: rgba(var(--now-indicator--primary_positive--background-color, 62, 134, 0), 0.15);
 color: rgb(var(--now-indicator--primary_positive--background-color, 62, 134, 0));
}
.status-badge--dismissed {
 background: rgba(var(--now-color_text--secondary, 75, 85, 89), 0.15);
 color: var(--ac-text-muted);
}

/* ===== Pagination ===== */
.pagination {
 display: flex;
 align-items: center;
 justify-content: space-between;
 padding: var(--ac-space-md) 0;
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--ac-text-muted);
}
.pagination__controls { display: flex; align-items: center; gap: var(--ac-space-md); }
.pagination__btn {
 padding: 0.375rem 0.75rem;
 border: 1px solid var(--ac-border);
 border-radius: var(--now-actionable--border-radius, 6px);
 background: var(--ac-bg);
 color: var(--ac-text);
 font-family: var(--ac-font);
 font-size: 0.75rem;
 cursor: pointer;
}
.pagination__btn:disabled { opacity: 0.4; cursor: not-allowed; }
.pagination__btn:not(:disabled):hover { background: var(--ac-bg-alt); }

/* ===== Empty State ===== */
.empty-state {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 padding: 4rem 2rem;
 text-align: center;
}
.empty-state__icon {
 width: 4rem;
 height: 4rem;
 display: flex;
 align-items: center;
 justify-content: center;
 border-radius: 50%;
 background: rgba(var(--now-indicator--primary_positive--background-color, 62, 134, 0), 0.12);
 color: rgb(var(--now-indicator--primary_positive--background-color, 62, 134, 0));
 font-size: 1.5rem;
 margin-bottom: var(--ac-space-lg);
}
.empty-state__heading {
 margin: 0 0 var(--ac-space-sm);
 font-size: var(--now-static-font-size--lg, 1.25rem);
 font-weight: 600;
}
.empty-state__message {
 margin: 0;
 color: var(--ac-text-muted);
 max-width: 400px;
 line-height: 1.5;
}

/* ===== Loading ===== */
.alerts-loading { display: flex; justify-content: center; padding: 4rem; }
.spinner {
 width: 2rem;
 height: 2rem;
 border: 3px solid rgba(var(--now-loading_indicator--primary--color, 0, 128, 163), 0.2);
 border-top-color: rgb(var(--now-loading_indicator--primary--color, 0, 128, 163));
 border-radius: 50%;
 animation: spin 1s linear infinite;
}
@keyframes spin { 100% { transform: rotate(360deg); } }

/* ===== Responsive ===== */
@media (max-width: 1200px) {
 .summary-cards { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 768px) {
 .summary-cards { grid-template-columns: repeat(2, 1fr); }
 .filter-bar { flex-direction: column; align-items: stretch; }
 .filter-bar__fields { flex-direction: column; }
}
","import React, { useState, useEffect, useCallback } from "react";
import SummaryCards from "./components/SummaryCards";
import FilterBar from "./components/FilterBar";
import AlertTable from "./components/AlertTable";
import EmptyState from "./components/EmptyState";
import { fetchAlerts } from "./services/alertService";
import type { AlertFilters, AlertResponse } from "./services/alertService";
import "./alerts-center.css";

const EMPTY_FILTERS: AlertFilters = {};
const PAGE_SIZE = 25;
const DEFAULT_SUMMARY = {
 critical: 0, high: 0, medium: 0, low: 0, open: 0, resolved: 0,
};

export default function App() {
 const [data, setData] = useState<AlertResponse | null>(null);
 const [filters, setFilters] = useState<AlertFilters>(EMPTY_FILTERS);
 const [offset, setOffset] = useState(0);
 const [loading, setLoading] = useState(true);

 const load = useCallback(async () => {
 setLoading(true);
 try {
 setData(await fetchAlerts(filters, PAGE_SIZE, offset));
 } catch (e) {
 console.error("Failed to fetch alerts", e);
 } finally {
 setLoading(false);
 }
 }, [filters, offset]);

 useEffect(() => { load(); }, [load]);

 const onFilter = (f: AlertFilters) => { setFilters(f); setOffset(0); };
 const onReset = () => { setFilters(EMPTY_FILTERS); setOffset(0); };

 const summary = data?.summary || DEFAULT_SUMMARY;
 const alerts = data?.alerts || [];
 const total = data?.total || 0;
 const types = data?.alertTypes || [];
 const page = Math.floor(offset / PAGE_SIZE) + 1;
 const pages = Math.max(1, Math.ceil(total / PAGE_SIZE));

 return (
 <div className="alerts-page">
 <header className="alerts-header">
 <h1 className="alerts-header__title">Alerts &amp; Exceptions</h1>
 <p className="alerts-header__subtitle">
 Centralized view of operational issues requiring attention.
 </p>
 </header>

 <SummaryCards summary={summary} />
 <FilterBar filters={filters} alertTypes={types}
 onFilterChange={onFilter} onReset={onReset} />

 {loading ? (
 <div className="alerts-loading"><div className="spinner" /></div>
 ) : alerts.length > 0 ? (
 <>
 <AlertTable alerts={alerts} />
 <div className="pagination">
 <span className="pagination__info">
 Showing {offset + 1}&ndash;{Math.min(offset + PAGE_SIZE, total)} of {total}
 </span>
 <div className="pagination__controls">
 <button className="pagination__btn" disabled={offset === 0}
 onClick={() => setOffset(Math.max(0, offset - PAGE_SIZE))}>
 &larr; Previous
 </button>
 <span className="pagination__page">
 Page {page} of {pages}
 </span>
 <button className="pagination__btn"
 disabled={offset + PAGE_SIZE >= total}
 onClick={() => setOffset(offset + PAGE_SIZE)}>
 Next &rarr;
 </button>
 </div>
 </div>
 </>
 ) : (
 <EmptyState />
 )}
 </div>
 );
}
","import React from "react";
import ReactDOM from "react-dom/client";
import App from "./app";

ReactDOM.createRoot(document.getElementById("root")!).render(<App />);
